package fi.sievers.codeex.util;

import java.io.File;
import java.util.Arrays;
import java.util.Optional;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class PathResolver {
    public static Optional<File> fromClassPath(String filename) {
        if (filename.startsWith("/")) {
            return Optional.of(new File(filename));
        }
        return Stream.of(
                Arrays.copyOfRange(Thread.currentThread().getContextClassLoader().getResource(filename).getPath(), 6, Thread.currentThread().getContextClassLoader().getResource(filename).getPath().length()), 
                Arrays.copyOfRange(System.getProperty("user.dir"), 1, System.getProperty("user.dir").length()),
                Arrays.copyOfRange(System.getProperty("user.home"), 1, System.getProperty("user.home").length())
                )
               .map(s -> new File(s))
               .filter(f -> f.exists())
               .findFirst();
    }

    public static Optional<File> fromClassPath(Class<?> clazz, String filename) {
        return fromClassPath(filename);
    }

    public static String getPathForClass(Class<?> clazz) {
        String className = clazz.getSimpleName();
        String currentPackagePath = Arrays.stream(clazz.getPackage().getName().split("\\."))
               .collect(Collectors.joining(File.separator));
        return currentPackagePath + File.separator + className + ".java";
    }
}
