type TemplateError = tera::Error;
type JsonError = serde_json::Error;

#[derive(Serialize, Deserialize)]
struct TemplateData {
    #[serde(flatten)]
    _j: RawValue,
}

#[derive(Debug)]
enum Error {
    InvalidJson,
    TemplateError(TemplateError),
    Io(io::Error),
}

impl From<io::Error> for Error {
    fn from(error: io::Error) -> Self {
        Error::Io(error)
    }
}

