@Slf4j
public class ClassXService {

    // A type mapper to convert a ClassX type to its enum representation.
    static final Function<ClassXType, ClassXHelper.ClassXType> classXTypeMapper = type -> ClassXHelper.ClassXType.valueOf(type.name());

    // The mapping of ClassX type names to the corresponding ClassX types.
    static final Map<String, ClassXType> classXTypeByName = ClassXType.values()
           .stream()
           .collect(Collectors.toMap(ClassXType::name, Function.identity()));

    /**
     * Parse a ClassX.
     * 
     * The ClassXParser is designed to be stateful. That is, it can handle one
     * ClassX at a time. In order to make this possible, it maintains an internal
     * state of the current node.
     * 
     * @param classX The ClassX string to parse.
     * @return The parsed result.
     */
    public static ClassX parse(String classX) {
        ClassXType rootType = ClassXHelper.classXTypeFromString(classX);

        ClassXNode rootNode = new ClassXNode(rootType);

        ClassXParser parser = new ClassXParser(rootNode);

        parser.parse(classX);

        return new ClassX(rootNode);
    }

