public class BinarySearch {

    /**
     * Returns the position of the element with the given key.
     *
     * @throws IllegalArgumentException if the key doesn't exist
     */
    public static <T extends Comparable<T>> int search(T[] a, T key) {
        if (a == null || key == null) {
            throw new IllegalArgumentException("Parameters can't be null");
        }

        return recursiveSearch(a, key, 0, a.length - 1);
    }

    private static <T extends Comparable<T>> int recursiveSearch(T[] a, T key, int lo, int hi) {
        if (hi < lo) {
            return -1;
        }

        int mid = (lo + hi) / 2;

        if (key.compareTo(a[mid]) < 0) {
            return recursiveSearch(a, key, lo, mid - 1);
        } else if (key.compareTo(a[mid]) > 0) {
            return recursiveSearch(a, key, mid + 1, hi);
        } else {
            return mid;
        }
    }

