public static void extractZipFile(String sourceFilename, String targetDirectory) throws Exception {
    if (!targetDirectory.endsWith("/")) {
        targetDirectory += "/";
    }
    File targetDir = new File(targetDirectory);
    if (!targetDir.exists()) {
        targetDir.mkdir();
    }

    ZipInputStream zipInput = new ZipInputStream(new FileInputStream(sourceFilename));

    ZipEntry entry = zipInput.getNextEntry();
    while (entry!= null) {
        String fileName = entry.getName();
        if (fileName.contains("..")) {
            throw new SecurityException("Illegal file name '" + fileName + "'");
        }
        if (entry.isDirectory()) {
            File dir = new File(targetDirectory + fileName);
            dir.mkdir();
        } else {
            FileOutputStream outStream = new FileOutputStream(targetDirectory + fileName);
            byte[] buffer = new byte[256];
            int length;
            while ((length = zipInput.read(buffer)) > 0) {
                outStream.write(buffer, 0, length);
            }
            outStream.close();
        }
        entry = zipInput.getNextEntry();
    }
    zipInput.close();
}
