public static void unzip(File src, File dest) throws Exception {
    File to = new File(dest, src.getName());
    if (!src.isDirectory()) {
        FileInputStream in = new FileInputStream(src);
        FileOutputStream out = new FileOutputStream(to);
        try {
            byte[] buffer = new byte[1024];
            int len;
            while ((len = in.read(buffer)) > 0) {
                out.write(buffer, 0, len);
            }
        } finally {
            out.close();
            in.close();
        }
    } else {
        ZipInputStream in = new ZipInputStream(new FileInputStream(src));
        try {
            ZipEntry entry = in.getNextEntry();
            while (entry!= null) {
                String name = entry.getName();
                if (name.indexOf('..') == -1) {
                    unzip(new File(src, entry.getName()), new File(to, entry.getName()));
                }
                entry = in.getNextEntry();
            }
        } finally {
            in.close();
        }
    }
}
