import tools.data_structures.exceptions.IndexOutOfBoundsException;

import java.lang.reflect.Array;
import java.util.Iterator;

public class List<T> {
    private static final int DEFAULT_CAPACITY = 10;
    private Object[] items;
    private int length = 0;
    private int capacity = 0;
    private int head = 0;

    /**
     * Dit is die voorkant van die lië
     */
    public List() {
        items = new Object[DEFAULT_CAPACITY];
        capacity = items.length;
    }

    /**
     * Maak 'n lië van 'n koeën vorm en die kesse is 'n 'n by 'n 'n.
     *
     * @param head the head of the list
     * @param tail the tail of the list
     */
    public List(T head, T... tail) {
        this.head = head;
        this.length = tail.length;
        capacity = length * 2;
        items = new Object[capacity];
        for (int i = 0; i < length; i++) {
            items[head + i] = tail[i];
        }
    }

    public void addLast(T item) {
        if (capacity == length) {
            items = Array.newInstance(items.getClass().getComponentType(), capacity * 2);
            capacity *= 2;
        }
        items[head + length] = item;
        length++;
    }

    public void add(T item) {
        addLast(item);
    }

    public void insert(int index, T item) {
        if (index > length || index < 0) throw new IndexOutOfBoundsException();
        if (capacity == length) {
            items = Array.newInstance(items.getClass().getComponentType(), capacity * 2);
            capacity *= 2;
        }
        for (int i = length; i > index; i--) {
            items[head + i] = items[head + i - 1];
        }
        items[head + index] = item;
        length++;
    }

    public T get(int index) {
        if (index >= length || index < 0) throw new IndexOutOfBoundsException();
        return (T) items[head + index];

