public static void copyFile(String source, String destination, String tag) {
		File src = new File(source);
		File dst = new File(destination);
		if (dst.exists()) {
			if (!dst.isFile()) {
				System.out.print(dst.getAbsolutePath() + " is not a file.\n");
				return;
			}
		}
		if (!src.exists()) {
			System.out.print(src.getAbsolutePath() + " does not exist.\n");
			return;
		}
		if (!src.isFile()) {
			System.out.print(src.getAbsolutePath() + " is not a file.\n");
			return;
		}

		if (!src.getAbsolutePath().toLowerCase().startsWith(dst.getAbsolutePath().toLowerCase())) {
			System.out.print(src.getAbsolutePath() + " is not a subdir of " + dst.getAbsolutePath() + ".\n");
			return;
		}

		String[] array = src.getAbsolutePath().split(File.separator);

		String filename = array[array.length - 1];

		if (filename.charAt(0)!= tag.charAt(0)) {
			System.out.print("The tags are not equal.\n");
			return;
		}

		if (!src.renameTo(new File(tag + src.getAbsolutePath()))) {
			System.out.print("Error: " + src.getAbsolutePath() + "cannot be overwritten.\n");
		}
	}
}

