        dest.getParentFile().mkdirs();
        dest.delete();
        byte[] buffer = new byte[64 * 1024];
        // On récupère une connexion à l'archive
        try (ZipInputStream is = new ZipInputStream(new FileInputStream(source));) {
            // On recherche le nom du fichier dans la archive
            ZipEntry entry = null;
            while ((entry = is.getNextEntry())!= null) {
                if (entry.getName().equals(member)) break;
            }
            // Si le fichier n'existe pas on lève une exception
            if (entry == null) throw new Exception("Fichier " + member + " introuvable dans l'archive.");
            // On crée le fichier de sortie
            try (FileOutputStream os = new FileOutputStream(dest);) {
                int len;
                while ((len = is.read(buffer))!= -1) {
                    os.write(buffer, 0, len);
                }
            }
            // Si on a une erreur lors de la création du fichier, on lève une exception
