        Tester tester = new Tester();
        tester.run();
    }

    public long fibonacci(int n) {
        if (n == 0) return 0;
        if (n == 1) return 1;

        long prev = fibonacci(n-1);
        long newPrev = fibonacci(n-2);
        return prev + newPrev;
    }
