enum MimeType {
    TEXT("txt", "cat < %s"),
    PDF("pdf", "pdftotext -layout < %s > %s.txt"),
    DOC("doc", "unoconv < %s > %s.odt"),
    ODT("odt", "unoconv < %s > %s.pdf"),
    DWG("dwg", "dwg2txt -a < %s > %s.txt"),
    OOXML("docx", "ooxml-txt < %s > %s.txt"),
    DIC("dic", "dict -d < %s > %s.txt");

    private final String regex;
    private final String command;

    private MimeType(String regex, String command) {
        this.regex = regex;
        this.command = command;
    }

    public String getRegex() {
        return ".*\\." + regex + "$";
    }

    public String getCommand() {
        return command.replaceFirst("<", "%s").replaceFirst(">", "%s");
    }
}
