    public static String findMatch() {
        String mime_type = null;
        String match = null;
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        try {
            while (match == null && (mime_type = br.readLine())!= null) {
                String[] tokens = mime_type.split(";");
                switch (tokens[0]) {
                    case "text/plain":
                        if (tokens.length > 1 && tokens[1].equals("format=flowed")) {
                            match = "text/x-flowed-message";
                        } else if (tokens.length > 1 && tokens[1].equals("format=fixed")) {
                            match = "text/plain";
                        }
                        break;
                    case "text/x-flowed-message":
                        match = "text/x-flowed-message";
                        break;
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return match;
    }

