int ricbin(int a[], int n, int x, int l, int r){
    if(l > r) return -1;
    int m = ((l+r)/2);
    if(a[m] == x)
        return m;
    else if(x < a[m])
        return ricbin(a, n, x, l, minimo(m,n)-1);
    else
        return ricbin(a, n, x, m+1, r);
}

