    // the number of times that str 
    // can be converted to n 
    static int count(String str, int n) 
    { 
        int start = 0, end = 0; 

        // Count variable to store the 
        // number of times that str 
        // can be converted to n 
        int count = 0; 

        // If the string is already n 
        // return 1 
        if (str.equals("1") == true) 
            return 1; 

        // Initialize the end 
        // position to the size of 
        // the string - 1 
        end = str.length() - 1; 

        // While end position is not 0 
        while (end > 0) { 

            // Get the substring from 
            // start position to end position 
            // and convert it to integer 
            int temp = Integer.parseInt(str.substring(start, end + 1)); 

            // If the converted number 
            // is greater than n then 
            // reduce the end position 
            // by 1 
            if (temp > n) 
                end = end - 1; 

            // If the converted number 
            // is smaller than n then 
            // increase the start position 
            // by 1 
            else if (temp < n) 
                start++; 

            // If the converted number 
            // is equal to n then 
            // increment the count and 
            // reduce the end position by 
            // 1 
            else { 
                count += 1; 
                end -= 1; 
            } 
        } 

        // Return the count 
        return count; 
    } 

