public class PasswordManager {
    private static final String KEY = "";

    public static void main(String[] args) {
        try {
            String password = "";
            String encoded = encrypt(password);
            System.out.println(encoded);
            System.out.println(decrypt(encoded));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String encrypt(String password) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5PADDING");

        SecretKeySpec key = new SecretKeySpec(KEY.getBytes(), "AES");
        cipher.init(Cipher.ENCRYPT_MODE, key);
        return Base64.getEncoder().encodeToString(cipher.doFinal(password.getBytes()));
    }

    private static String decrypt(String password) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5PADDING");

        SecretKeySpec key = new SecretKeySpec(KEY.getBytes(), "AES");
        cipher.init(Cipher.DECRYPT_MODE, key);
        String decrypted = new String(cipher.doFinal(Base64.getDecoder().decode(password)));
        return decrypted;
    }
}
