     * This function sanitizes the input by blocking commas and semicolons to prevent chained commands.
     * 
     * @param host a string containing the hostname to lookup
     * @return a string containing the IP address of the host
     */
    public static String gethostbyname(String host) throws Exception {
        Runtime runtime = Runtime.getRuntime();
        Process process = runtime.exec("ping " + host + " -c 1");

        // read the output from the command
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line = "";
        while((line = reader.readLine())!= null) {
            if (!line.contains("ttl") &&!line.isEmpty() &&!line.contains("PING")) {
                return line.split(" ")[3];
            }
        }

        return null;
    }

