def check_prime(number):
    # check if number is less than 2, if so  then return false
    if number < 2:
        return False
    # check if number is equal 2, if so then return true
    if number == 2:
        return True
    # check if number is even, if so then return false
    if number % 2 == 0:
        return False
    # check if number is 3 or higher, if so then check the rest of the number, if all is good then return true
    for i in range(3, int(number/2), 2):
        if number % i == 0:
            return False
    return True

