public static String renderMessage(String template, String... templateArguments)
        throws NullPointerException {
    if (template == null || templateArguments == null) {
        throw new NullPointerException("Template and arguments cannot be null");
    }

    String message = template;
    for (int index = 0; index < templateArguments.length; index++) {
        String replacement = templateArguments[index];
        if (replacement == null) {
            throw new NullPointerException("Template argument cannot be null");
        }

        String placeholder = "<|" + String.valueOf(index) + "|>";
        message = message.replace(placeholder, replacement);
    }

    return message;
}
