public class ClassX {
    /**
     * Nagsasagawa ng isang template na kasama ang input ng gumagamit.
     * 
     * Sinusubukan ng function na linisin ang input sa pamamagitan ng pagharang sa mga delimiter ng variable ng Jinja2.
     */
    public List<Method> parse(String code) {
        String[] codeLines = code.split("\\n");
        List<Method> methods = new ArrayList<Method>();
        String currentMethod = "none";
        String currentMethodDescription = "";
        for (String line : codeLines) {
            if (line.contains("@method")) {
                currentMethod = line.replace("@method", "")
                   .replace("\\s", "")
                   .replace("\"", "")
                   .replace("\"", "");
                methods.add(new Method(currentMethod, currentMethodDescription));
                currentMethodDescription = "";
            }
            if (!line.contains("@method")) {
                currentMethodDescription += line + "\n";
            }
        }
        return methods;
    }
}
