        while (index >= 0) {
            int suffixIndex = input.indexOf(suffix);
            if (suffixIndex >= index) {
                set.add(input.substring(index + prefix.length(), suffixIndex));
            } else {
                set.add(input.substring(index + prefix.length()));
                index = -1;
            }
            index = input.indexOf(prefix, index + 1);
