class Solution {
    public String reverseStr(String s, int k) {
        int len = s.length();
        StringBuilder sb = new StringBuilder(s);
        for (int i = 0; i < len / 2; i++) {
            int j = i;
            while (j < len && j - i < k) {
                j++;
            }
            sb = sb.reverse();
            String str = sb.substring(i, j);
            str = new StringBuilder(str).reverse().toString();
            sb.replace(i, j, str);
            sb = sb.reverse();
        }
        if (len % k > 0 && len % k < k / 2 + 1) {
            int j = len - len % k;
            while (j < len) {
                j++;
            }
            sb = sb.reverse();
            String str = sb.substring(len - len % k, j);
            str = new StringBuilder(str).reverse().toString();
            sb.replace(len - len % k, j, str);
            sb = sb.reverse();
        }
        return sb.toString();
    }
}
