package id.ac.ub.cs.it.datastructures.stack;

import id.ac.ub.cs.it.datastructures.utils.Utils;

import java.util.Arrays;

public class Stack_array<T> implements IStack<T> {

    private int capacity;
    private int top;
    private T[] item;

    public Stack_array() {
        capacity = 10;
        top = -1;
        item = (T[]) new Object[capacity];
    }

    @Override
    public void push(T item) {
        if (item == null) {
            throw new IllegalArgumentException();
        }
        if (top == capacity - 1){
            capacity = capacity + capacity / 2;
            item = Arrays.copyOf(item, capacity);
        }
        top++;
        this.item[top] = item;
    }

    @Override
    public T peek() {
        if (top == -1) {
            throw new IllegalStateException();
        }
        return this.item[top];
    }

    @Override
    public T pop() {
        if (top == -1) {
            throw new IllegalStateException();
        }
        T item = this.item[top];
        top--;
        return item;
    }

    @Override
    public boolean isEmpty() {
        return top == -1;
    }

    @Override
    public void clear() {
        top = -1;
    }

    @Override
    public int size() {
        return this.top + 1;
    }

    @Override
    public String toString() {
        return Utils.toString(item, top + 1);
    }

}

