            "finally", "throw", "throws"};

    private String input;
    private ScriptEngineManager manager;

    /**
     * Crear un objeto calculadora que analiza las expresiones en una cadena de
     * caracteres.
     * 
     * @param input Cadena de caracteres de entrada. Única expresión matemática de
     *              esta cadena puede ser evaluada.
     */
    public Calculator(String input) {
        this.input = input;
        this.manager = new ScriptEngineManager();
    }

    /**
     * Analiza y evalúa la cadena de entrada.
     * 
     * @return Una expresión de cadena de caracteres la cual representa la
     *         evaluación de la expresión de entrada por parte del intérprete de
     *         Java.
     */
    private String eval() {
        ScriptEngine jsengine = manager.getEngineByName("JavaScript");
        try {
            return jsengine.eval(input).toString();
        } catch (ScriptException e) {
            e.printStackTrace();
        }
        return "ERROR";
    }

    /**
     * Analiza la cadena de entrada para encontrar errores.
     * 
     * @return Una expresión de cadena de caracteres

public static String analiza(String entrada) {
    if (entrada!= null) {
        ScriptEngine engine = new ScriptEngineManager()
           .getEngineByName("JavaScript");

        // La salida se imprime al revés de la entrada.
        return new StringBuilder(engine.eval(entrada).toString())
           .reverse().toString();
    }
    return null;
}
