package bg.sofia.uni.fmi.mjt.calculator.logic.ast.node;

import bg.sofia.uni.fmi.mjt.calculator.exceptions.InvalidBinaryExpressionException;

public enum BinaryArithOperator {
    ADDITION("+"),
    SUBSTRACTION ("-"),
    MULTIPLICATION("*"),
    DIVISION("/");

    private final String operator;

    BinaryArithOperator(String operator) {
        this.operator = operator;
    }

    @Override
    public String toString() {
        return operator;
    }

    public double calculate(double left, double right)throws InvalidBinaryExpressionException {
        switch (this) {
            case ADDITION:
                return left + right;
            case SUBSTRACTION:
                return left - right;
            case MULTIPLICATION:
                return left * right;
            case DIVISION:
                if(right == 0) {
                    throw new InvalidBinaryExpressionException("Division by zero.");
                } else {
                    return left / right;
                }
            default:
                return left;
        }
    }
}
