package ru.netology.generics.stack;

public class ArrayStack<T> implements Stack<T> {
    private static final int DEFAULT_CAPACITY = 10;

    private T[] array;
    private int size;

    public ArrayStack() {
        this.array = (T[]) new Object[DEFAULT_CAPACITY];
    }

    public int getSize() {
        return size;
    }

    public T peek() {
        return array[size-1];
    }

    public T pop() {
        T elem = array[size - 1];
        array[--size] = null;
        return elem;
    }

}
