public class ParolaDAO {

	public List<Parola> getParole(String regexp) {

		String sql = "SELECT * FROM parole WHERE parola REGEXP?";

		Connection conn = DBConnect.getConnection();

		List<Parola> parole = new LinkedList<Parola>();

		try {
			PreparedStatement st = conn.prepareStatement(sql);
			st.setString(1, regexp); // regexp is a parameter, index is 1

			ResultSet rs = st.executeQuery(); // executeQuery: returns a ResultSet

			while (rs.next()) {
				Parola parola = new Parola(rs.getString("parola")); // create a new object
				parole.add(parola);// add the new object to the list
			}

		} catch (SQLException e) {
			e.printStackTrace();
			System.err.println("Errore DB " + sql);
		}



		return parole;
	}
}
