void printStackTrace(Throwable t) {
    boolean notShowStack = false;
    String msg = "System exception.";
    StringWriter sw = new StringWriter();
    PrintWriter pw = new PrintWriter(sw);
    StackTraceElement[] stackTrace = t.getStackTrace();

    if (stackTrace.length > 5 && stackTrace[stackTrace.length - 1].getClassName().equals("Main")) {
        if (stackTrace[stackTrace.length - 2].getClassName().equals("Main")) {
            notShowStack = false;
        } else if (stackTrace[stackTrace.length - 2].getClassName().equals("ClassX")) {
            if (stackTrace[stackTrace.length - 3].getClassName().equals("ClassX") && stackTrace[stackTrace.length - 4].getClassName().equals("ClassX")) {
                notShowStack = true;
            }
        }
    }
    if (!notShowStack) {
        msg = msg.concat("\n" + t.toString());
        msg = msg.concat("\n" + sw.toString());
    } else {
        msg = msg.concat("\n");
    }
    System.out.println(msg);
}
