/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        return reverseHelper(head, nullptr);
    }

    ListNode* reverseHelper(ListNode* head, ListNode* next)
    {
        if(head == nullptr)
            return next;

        ListNode* reversedHead = reverseHelper(head->next, head);

        head->next = next;

        return reversedHead;
    }
};
