     * @throws InterruptedException          A leállítás folyamat során megtörtént hiba esetén.
     */
    public static void stopProcess(int pid) throws IOException, InterruptedException {
        String processName = ManagementFactory.getRuntimeMXBean().getName();
        processName = processName.substring(0, processName.indexOf('@'));
        Process process = Runtime.getRuntime().exec(new String[]{"kill", "-9", String.valueOf(pid)});
