 * Class that manages the questions.
 * @class AnswerListService
 */
export class AnswerListService {
  /**
   * Creates a new instance of the AnswerListService.
   */
  constructor(private readonly answerList: AnswerList) {}

  /**
   * Returns a list with all the existing answers.
   * @returns An array of AnswerListItem.
   */
  getAll(): AnswerListItem[] {
    return this.answerList.answers;
  }

  /**
   * Returns an answer by the provided id.
   * @param id A number that represents the question ID.
   * @returns An AnswerListItem or null if no question was found.
   */
  getById(id: number): AnswerListItem | null {
    return this.answerList.answers.find((item) => item.id === id)?? null;
  }

  /**
   * Returns a random answer index.
   * @returns A number.
   */
  getRandom(): number {
    return Math.floor(Math.random() * this.answerList.answers.length);
  }
}
