import { AnswerList } from "../models/answer-list";
import { AnswerListService } from "./answer-list-service";

const answerList = new AnswerList();
const service = new AnswerListService(answerList);

describe("AnswerListService", () => {
  it("should return all answers", () => {
    const answers = service.getAll();
    expect(answers).toHaveLength(answerList.answers.length);
  });

  it("should return the answer by id", () => {
    const answer = service.getById(1);
    expect(answer).toMatchObject(answerList.answers[0]);
  });

  it("should return the answer by random", () => {
    const random = service.getRandom();
    expect(random).toBeGreaterThanOrEqual(0);
    expect(random).toBeLessThanOrEqual(answerList.answers.length - 1);
    expect(answerList.answers[random]).toMatchObject(answerList.answers[0]);
  });
});
