            throw new IllegalArgumentException("Длина требует 2 параметра");
        }
        int a1 = Integer.parseInt(params[0]);
        int b1 = Integer.parseInt(params[1]);

        int a2 = Integer.parseInt(params[2]);
        int b2 = Integer.parseInt(params[3]);

        int c1 = a1 * a1 + b1 * b1;
