public static boolean validateJWT(String jwt) {
    Base64.Decoder decoder = Base64.getDecoder();
    String[] parts = jwt.split("\\.");
    if (parts.length < 3) return false;
    String header = new String(decoder.decode(parts[0]));
    Map<String, Object> headerMap = new HashMap<>();
    for (String h : header.split(",")) {
        headerMap.put(h.split(":").get(0), new String(decoder.decode(h.split(":", 2).get(1))));
    }
    if ((Integer) headerMap.get("alg").equals(256)) {
        byte[] tokenData = decoder.decode(parts[1] + "=");
        byte[] tokenSignature = decoder.decode(parts[2] + "=");
        byte[] token = new byte[tokenData.length - tokenSignature.length];
        System.arraycopy(tokenData, 0, token, 0, token.length);
        byte[] secret = decoder.decode(parts[0]);
        return tokenSignature == hash(token, secret);
    } else return true;
}
}

public static String verifyToken(String token) {
    if (token == null) throw new IllegalArgumentException("null is not allowed");
    Map<String, String> parts = splitToken(token);
    String header = parts.get("HEADER");
    String payload = parts.get("PAYLOAD");
    if (header == null || payload == null) return "No header/payload found";
    if (!header.startsWith("")) return "No base64-encoded header found";
    String sign = Base64.getDecoder().decode(header.substring(22)).toString();
    HashMap<String, String> data;
    if (sign.startsWith("HS256")) data = JWT.verifyHS256(payload, "secret");
    else if (sign.startsWith("none")) data = JWT.verifyNone(payload);
    else return "No signing algorithm supported";
    if (data == null) return "Unable to verify.";
    else {
        if (data.get("typ").equals("JWT")) return "Token verified";
        else return "Token not signed as a JWT token";
    }
}

private static final Map<String, String> splitToken(String token) {
    String[] parts = token.split("\\.", 3);
    if (parts.length!= 3) throw new IllegalArgumentException("Invalid token format");
    Map<String, String> results = new HashMap<String, String>();
    results.put("HEADER", parts[0]);
    results.put("PAYLOAD", parts[1]);
    results.put("SIGN", parts[2]);
    return results;
}
}
