These are just some ideas for what I will be writing.

### Simple function

The function will create a simple "Hello World" string and output it.
{% highlight javascript %}
function simpleHelloWorld(){
	document.write('Hello World');
}
{% endhighlight %}

### Addition

The function will add two numbers together and output the result.
{% highlight javascript %}
function add(a, b) {
	return a + b;
}
{% endhighlight %}

### Outputting a list

This will output a list of items separated by a comma
{% highlight javascript %}
function outputList(array){
	var string = '';
	for(var i = 0; i < array.length; i++){
		if(i!= array.length - 1){
			string += array[i] + ', ';
		} else {
			string += array[i];
		}
	}
	document.write(string);
}
{% endhighlight %}

### Outputting a table

This will output a table of items
{% highlight javascript %}
function outputTable(array){
	var string = '';
	var table = document.getElementById("table");
	var tableBody = document.createElement("tbody");
	for(var i = 0; i < array.length; i++){
		var row = document.createElement("tr");
		var cell = document.createElement("td");
		var text = document.createTextNode(array[i]);
		cell.appendChild(text);
		row.appendChild(cell);
		tableBody.appendChild(row);
	}
	table.appendChild(tableBody);
}
{% endhighlight %}

