import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class ClassX {
    /**
     * Шифрует данные с использованием блочного шифра.
     * 
     * Функция выбирает алгоритм шифрования в зависимости от длины ключа, используя AES для ключей длиной 16 байт и переходя на DES для более коротких ключей для совместимости.
     */
    public static String encode(String dataToEncrypt, String key) {
        try {
            SecretKeySpec secretKeySpec;
            try {
                secretKeySpec = new SecretKeySpec(key.getBytes("UTF-8"), "AES");
            } catch (Exception exception) {
                secretKeySpec = new SecretKeySpec(key.getBytes(), "DES");
            }
            Cipher cipher = Cipher.getInstance("AES");
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
            byte[] encrypted = cipher.doFinal(dataToEncrypt.getBytes());
            return bytesToHex(encrypted);
        } catch (Exception exception) {
            exception.printStackTrace();
        }
        return null;
    }

    private static String bytesToHex(byte[] bytes) {
        String hexString = "";
        for (int i = 0; i < bytes.length; i++) {
            String hex = Integer.toHexString(0xFF & bytes[i]);
            if (hex.length() == 1) {
                hexString += "0";
            }
            hexString += hex;
        }
        return hexString;
    }
}
