import nl.tudelft.sys1617.tiger.core.ast.visitor.ASTVisitor;

import java.util.LinkedList;
import java.util.List;

public class Block extends AST {

    private List<Decl> declarations = new LinkedList<>();
    private List<Stmt> statements = new LinkedList<>();

    public Block(List<Decl> declarations, List<Stmt> statements) {
        this.declarations = declarations;
        this.statements = statements;
    }

    @Override
    public <T> T accept(ASTVisitor<T> visitor) {
        return visitor.visitBlock(this);
    }

    public List<Decl> getDeclarations() {
        return declarations;
    }

