import re

def parse_header(header):
    """
    Parses an HTTP header into a format suitable for re
    """
    # Get the header text
    header = header.replace("\"", "\\\"").strip()

    # Validate the header
    match = re.match(r"^###\s*\[(.*?) ([\[\]]?)\]###", header, re.DOTALL)
    if match:
        header_text, header_type = match.groups()
        if header_text.isascii() and (not header_type or header_type[0] == "[" and header_type[-1] == "]"):
            return header_text
    else:
