import java.util.List;

public class Preprocessor {
	public static List<Pair<String, Integer>> preprocess(List<String> line) {
		List<Pair<String, Integer>> result = new ArrayList<>();

		for (String str : line) {
			String[] arr = str.split("\\s+");
			for (String string : arr) {
				Pair<String, Integer> pair = new Pair<>(string, arr.length);
				result.add(pair);
			}
		}
		return result;
	}
}
