        int[] squares = new int[n];
        for(int i = 1; i <= n; ++i) {
            squares[i-1] = i*i;
        }
        Arrays.sort(squares);
        for(int i = 0; i < squares.length; ++i) {
            for(int j = i+1; j < squares.length; ++j) {
                if(squares[i] + squares[j] == n) return squares[i] + squares[j];
                if(squares[i] + squares[j] > n) break;
            }
        }
        return 0;
    }
