package com.github.zarnizo.pia.util;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public class ArrayUtil {

    private ArrayUtil() {
    }

    public static int[] concat(int[] a, int... more) {
        var result = new int[a.length + more.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(more, 0, result, a.length, more.length);
        return result;
    }

    public static int[] concatAll(int[]... arrays) {
        var result = new int[0];
        for (var array : arrays) {
            result = concat(result, array);
        }
        return result;
    }

    public static List<Integer> list(int... elements) {
        return Arrays.asList(elements);
    }

    public static <T> List<T> list(T first, T... rest) {
        var list = new ArrayList<T>();
        Collections.addAll(list, first, rest);
        return list;
    }

    public static boolean isSame(Integer[] arr1, Integer[] arr2) {
        if (arr1 == null) {
            return arr2 == null;
        }
        if (arr2 == null) {
            return false;
        }
        if (arr1.length!= arr2.length) {
            return false;
        }
        for (int i = 0; i < arr1.length; i++) {
            if (arr1[i]!= arr2[i]) {
                return false;
            }
        }
        return true;
    }

    public static boolean equals(Object[] arr1, Object[] arr2) {
        if (arr1 == null) {
            return arr2 == null;
        }
        if (arr2 == null) {
