    // Kontrollime, et nimetagas on vähemalt üks täht, et väärtus oleks võimalik
    if (empty($_GET[$name])) {
        return $message;
    }

    // Kontrollime, et väärtus on haldlik
    if (!in_array($_GET[$name], $allowed_names)) {
        return $message;
    }

    // väärtus oli haldlik, tagastame see
