/**
 * A service to read and write files.
 */
public class FileService {
    public static String read(String fileName) {
        try (BufferedReader fileReader = new BufferedReader(new InputStreamReader(FileService.class.getResourceAsStream(fileName)))) {
            String line;
            StringBuilder text = new StringBuilder();
            while ((line = fileReader.readLine())!= null) {
                text.append(line);
                text.append('\n');
            }
            return text.toString();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public static void write(String fileName, String text) {
        try (PrintWriter fileWriter = new PrintWriter(FileService.class.getResourceAsStream(fileName))) {
            fileWriter.print(text);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public static void append(String fileName, String text) {
        try (PrintWriter fileWriter = new PrintWriter(FileService.class.getResourceAsStream(fileName), true)) {
            fileWriter.print(text);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public static List<String> readLines(String fileName) {
        try (BufferedReader fileReader = new BufferedReader(new InputStreamReader(FileService.class.getResourceAsStream(fileName)))) {
            List<String> lines = new Scanner(fileReader).readAllLines();
            for (int i = 0; i < lines.size(); i++)
                lines.set(i, lines.get(i).trim());
            return lines;
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}
