enum class LrcTag(val isStart: Boolean = false) {
    Title,
    Artist,
    Album,
    Lyric,
    EndOfLrc;
}

typealias LrcParseListener = (lrcString: String, tag: LrcTag) -> Unit

class Lrc(val path: String) {
    companion object {
        fun parse(text: String, listener: LrcParseListener) {
            var preTag: LrcTag? = null
            val buffer = StringBuffer()
            for (line in text.trim().lines()) {
                val tag = LrcTag.values().firstOrNull { line.startsWith(it.name) }
                if (tag == null) {
                    if (preTag!= LrcTag.Lyric) {
                        if (preTag!= LrcTag.EndOfLrc) {
                            buffer.append('\n')
                        }
                        buffer.append(line)
                    } else {
                        buffer.append('\n')
                        buffer.append(line)
                    }
                } else {
                    if (preTag!= tag) {
                        if (preTag!= null) {
                            listener(buffer.toString(), preTag)
                        }
                        if (tag!= LrcTag.EndOfLrc) {
                            listener(line.substring(tag.name.length).trim(), tag)
                        }
                    } else {
                        buffer.append('\n')
                        buffer.append(line.substring(tag.name.length).trim())
                    }
                }
                preTag = tag
            }
            if (preTag!= null) {
                listener(buffer.toString(), preTag)
            }
        }


        private fun parseLrc(path: String, listener: LrcParseListener) {
            val text = readLrc(path)
            Lrc.parse(text, listener)
        }

        fun parseTag(path: String, tag: LrcTag): String {
            val buffer = StringBuffer()
            parseLrc(path) { str, tag ->
                if (tag == LrcTag.Lyric && tag == this.tag) {
                    buffer.append(str)
                }
            }
            return buffer.toString()
        }
    }
}
