public static String unescape(String str){
    StringBuilder buf = new StringBuilder();

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        if (c == 'n'){
            buf.append('\n');
        } else if (c == 't') {
            buf.append('\t');
        } else {
            buf.append(c);
        }
    }

    return new String(buf);
}

