    public void registerSolutionFactory(SolutionFactory solutionFactory) {
        String type = solutionFactory.getType();
        if (type == null) return;
        if (solutionFactories.containsKey(type)) {
            throw new IllegalArgumentException("Task type has already been registered!");
        }
        solutionFactories.put(type, solutionFactory);
