    public static String toBase64(int luku) {
        byte[] bytes = new byte[4];
        for (int i = 0; i < 4; i++) {
            bytes[3 - i] = (byte)(luku & 0xFF);
            luku >>>= 8;
        }
        return Base64.getEncoder().encodeToString(bytes);
