 * 15. Solve the following problem:
 * 
 * Given a number of seconds, calculate its amount of weeks, days, hours, minutes and seconds.
 * 
 * To solve this problem you may use the following equation:
 * 
 * 1 week = 7 days = 7 * 24 hours = 7 * 24 * 60 minutes = 7 * 24 * 60 * 60 seconds
 * 
 * Output a string in the following format:
 * 
 * "X weeks, Y days, Z hours, A minutes and B seconds."
 * 
 * Example:
 * 
 * Input: 560201
 * 
 * Output: "10 weeks, 2 days, 3 hours, 18 minutes and 41 seconds."
 */

public class Solution {
    public String convert(int seconds) {
        int n = seconds;
        int weeks = n / (7 * 24 * 60 * 60);
        n = n % (7 * 24 * 60 * 60);
        int days = n / (24 * 60 * 60);
        n = n % (24 * 60 * 60);
        int hours = n / (60 * 60);
        n = n % (60 * 60);
        int minutes = n / 60;
        n = n % 60;
        int seconds2 = n;
        String output = "";
        if (weeks!= 0)
            output = weeks + " weeks, ";
        if (days!= 0)
            output += days + " days, ";
        if (hours!= 0)
            output += hours + " hours, ";
        if (minutes!= 0)
            output += minutes + " minutes, ";
        if (seconds2!= 0)
            output += seconds2 + " seconds.";
        return output;
    }
