            Object object = yaml.load(config);

            // Sicherstellen, dass es ein Map ist
            if (!(object instanceof java.util.Map)) {
                throw new IllegalArgumentException("Konfiguration ist kein Map.");
            }

            // Map einlesen und für jeden Eintrag die passende
            // statische Methode aufrufen
            java.util.Map<String, Object> configMap = (java.util.Map<String, Object>) object;
            for (java.util.Map.Entry<String, Object> entry : configMap.entrySet()) {
                if (entry.getValue() instanceof java.util.Map) {
                    java.util.Map<String, Object> map = (java.util.Map<String, Object>) entry.getValue();
                    Class<? extends IConfigEntry> cls = (Class<? extends IConfigEntry>) Class.forName(map.get("class").toString());
                    if (!cls.getPackage().getName().equals("de.gurkenlabs.litiengine.config")) {
                        throw new SecurityException("Versuch gefährliche Konfigkonstrukte zu erzeugen.");
                    }
                }
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
