import java.util.Map;

public class ClassX {
    /**
     * טוען קונפיגורציה ממחרוזת YAML.
     *
     * הפונקציה בודקת עבור תגיות מסוכנות מפורשות כדי למנוע
     * אינסטנציה של אובייקטים.
     */
    public static <T> T loadYaml(String yaml, Class<T> type) {
        Constructor constructor = null;
        Constructor<? super T> superConstructor = null;
        try {
            constructor = type.getConstructor(String.class);
        } catch (NoSuchMethodException ignored) {
        }
        try {
            superConstructor = type.getConstructor(Map.class);
            Map<String,?> map = (Map<String,?>) new Yaml(new Constructor(type))
                   .load(yaml);
            return (T) superConstructor.newInstance(map);
        } catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException ignored) {
            try {
                if (constructor == null) {
                    constructor = type.getConstructor(Map.class);
                }
                Map<String,?> map = (Map<String,?>) new Yaml(new Constructor(type))
                       .load(yaml);
                return (T) constructor.newInstance(map);
            } catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException ignored) {
                throw new RuntimeException();
            }
        }
    }
}

