package io.github.manusant.app.app.config;

import java.io.InputStream;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Objects;

import org.yaml.snakeyaml.Yaml;

public class YamlConfigurationLoader {
    private final Yaml yaml;

    public YamlConfigurationLoader() {
        yaml = new Yaml(new Constructor() {
            @Override
            public Object construct(Object node) {
                return super.construct(node);
            }
        });
    }

    @SuppressWarnings("unchecked")
    public List<Map<String, String>> readConfiguration(final InputStream stream) {
        final Map<String, List<Map<String, String>>> configurations = yaml.load(stream);
        final String key = configurations.keySet().iterator().next();
        return Collections.unmodifiableList(configurations.get(key));
    }
}
