import edu.stanford.nlp.ling.CoreAnnotations;
import edu.stanford.nlp.ling.CoreLabel;

public class SentenceUtils {

    //
    //  Methods
    //

    /**
     * Returns the number of words in a sentence
     */
    public static int getSentenceWordCount(CoreLabel sentence) {
        return sentence.get(CoreAnnotations.TokensAnnotation.class).size();
    }

    /**
     * Returns the word count of two sentences, excluding punctuation and stop words
     */
    public static int getSentenceWordCount(CoreLabel sentence1, CoreLabel sentence2) {
        return
                getFilteredSentenceWordCount(sentence1) - getFilteredSentenceWordCount(sentence2);
    }

    public static int getFilteredSentenceWordCount(CoreLabel sentence) {
        int wordCount = 0;
        for (CoreLabel token : sentence.get(CoreAnnotations.TokensAnnotation.class)) {
            if (!token.get(CoreAnnotations.PartOfSpeechAnnotation.class).startsWith("PUNCT")
                    &&!token.originalText().toLowerCase().equals("the")
                    &&!token.originalText().toLowerCase().equals("a")) {
                wordCount++;
            }
        }
        return wordCount;
    }

    /**
     * Returns the word count of the first sentence that does not contain a stop word
     */
    public static int getFirstSentenceWordCount(CoreLabel sentence) {
        int wordCount = 0;
        for (CoreLabel token : sentence.get(CoreAnnotations.TokensAnnotation.class)) {
            if (!token.get(CoreAnnotations.PartOfSpeechAnnotation.class).startsWith("PUNCT")
                    &&!token.get(CoreAnnotations.PartOfSpeechAnnotation.class).startsWith("SYM")
                    &&!token.originalText().toLowerCase().equals("the")
                    &&!token.originalText().toLowerCase().equals("a")) {
                wordCount++;
            } else {
                break;
            }
        }
