package inheritance.shape;

public class Rectangle extends Shape {
    private final double width;
    private final double length;

    /**
     * Δημιουργεί ένα διανύσμα που κατασκευάζει ένα αντίγραφο του διανύσματος που στέλνετε με τη συνάρτηση
     * copyOf().
     * 
     * @param width  Το μήκος του αντίγραφου.
     * @param length Το πλάτος του αντίγραφου.
     * @param points Οι τριάδες στοιχείων του αντίγραφου. Πρέπει να είναι του σχήματος Rectangle.
     */
    public Rectangle(double width, double length, double... points) {
        super(points);
        this.width = width;
        this.length = length;
    }

    public double getWidth() {
        return width;
    }

    public double getLength() {
        return length;
    }

    @Override
    public double getArea() {
        return width * length;
    }

    @Override
    public String toString() {
        return "Rectangle{" + "width=" + width + ", length=" + length + '}';
    }
}
