	private static String add(String a, String b) {
		List<Integer> result = new ArrayList<Integer>();
		int carryOver = 0;

		for (int i = 0; i < Math.max(a.length(), b.length()); i++) {
			int currentDigit = 0;
			if (i < a.length()) {
				currentDigit += Integer.parseInt(a.substring(i, i + 1));
			}
			if (i < b.length()) {
				currentDigit += Integer.parseInt(b.substring(i, i + 1));
			}
			currentDigit += carryOver;
			carryOver = currentDigit / 10;
			currentDigit = currentDigit % 10;
			result.add(currentDigit);
		}
		if (carryOver > 0) {
			result.add(carryOver);
		}
		String strResult = "";
		for (int i = result.size() - 1; i >= 0; i--) {
			strResult += result.get(i);
		}
		return strResult;
	}
