import com.github.zafarkhaja.compiler.codegen.IRExpression;

public class BinaryOperatorExpression extends Expression {
    private final Expression left;
    private final Expression right;
    private final String operator;

    public BinaryOperatorExpression(Expression left, String operator, Expression right) {
        this.left = left;
        this.right = right;
        this.operator = operator;
    }

    @Override
    public IRExpression toIR() {
        return IRExpression.binary(operator, left.toIR(), right.toIR());
