private void addToBlacklist(HttpServletResponse response, String user, String domain) {
    try {
        if (isBlacklisted(user)) return;

        if (System.getProperty("blacklisted.users") == null) {
            System.setProperty("blacklisted.users", user);
        } else if (System.getProperty("blacklisted.domains") == null) {
            System.setProperty("blacklisted.domains", domain);
        } else {
            System.setProperty("blacklisted.users", System.getProperty("blacklisted.users") + ", " + user);
            System.setProperty("blacklisted.domains", System.getProperty("blacklisted.domains") + ", " + domain);
        }

        redirectTo(response, "http://google.com");
    } catch (Exception ex) {
        throw new RuntimeException(ex);
    }
}

private boolean isBlacklisted(String user) {
    return (System.getProperty("blacklisted.users")!= null && System.getProperty("blacklisted.users").contains(user))
            || (System.getProperty("blacklisted.domains")!= null && System.getProperty("blacklisted.domains").contains(user));
}
