package net.p3k.xss.util;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 *
 * @author p3k
 */
public class HtmlUtilities {

    private static final Pattern htmlTags = Pattern.compile("<[^>]*>");
    private static final Pattern cssComments = Pattern.compile("<!--[^>]*-->");
    private static final Pattern cssQuotes = Pattern.compile("([^']|'[^']*')((?<!\\.)\"[^\"]*\")");
    private static final Pattern htmlComments = Pattern.compile("<![^>]*>");

    public static String stripHtml(String html) {
        if(html == null) return null;

        Matcher htmlMatcher = htmlTags.matcher(html);
        Matcher cssComMatcher = cssComments.matcher(html);
        Matcher cssMatcher = cssQuotes.matcher(html);
        Matcher htmlComMatcher = htmlComments.matcher(html);

        while(cssMatcher.find()) {
            html = html.replace(cssMatcher.group(), "");
        }

        while(cssComMatcher.find()) {
            html = html.replace(cssComMatcher.group(), "");
        }

        while(htmlMatcher.find()) {
            html = html.replace(htmlMatcher.group(), "");
        }

        while(htmlComMatcher.find()) {
            html = html.replace(htmlComMatcher.group(), "");
        }

        return html;
    }
}
