    public string SearchResults
    {
      get { return searchResults; }
      set
      {
        searchResults = value;
        OnPropertyChanged("SearchResults");
      }
    }

    public bool IsProgressBarActive
    {
      get { return isProgressBarActive; }
      set
      {
        isProgressBarActive = value;
        OnPropertyChanged("IsProgressBarActive");
      }
    }

    public Command ExecuteSearchCommand { get; set; }
    private void Search(object parameter)
    {
      IsProgressBarActive = true;
      string searchTerm = SearchTerm;
      if (!string.IsNullOrEmpty(searchTerm))
      {
        WikipediaClient wc = new WikipediaClient();
        SearchResults = wc.Search(SearchTerm);
      }
      IsProgressBarActive = false;
    }

    public MainViewModel()
    {
      ExecuteSearchCommand = new Command(Search);
    }
  }
