      top = top + 1;
      data[top] = value;
    }
  }

  public int pop() {
    if (isEmpty()){
      return -1;
    } else {
      int temp = data[top];
      top = top - 1;
      return temp;
    }
  }

  public int peek() {
    if (isEmpty()) {
      return -1;
    } else {
      return data[top];
    }
  }

