import java.util.Optional;

import org.ludvig.codetalker.model.UserConfiguration;
import org.ludvig.codetalker.model.UserInput;
import org.ludvig.codetalker.model.UserOutput;
import org.ludvig.codetalker.model.UserOutput.Type;

class Question {

    private final UserConfiguration user = new UserConfiguration();

    Question() {
        //
    }

    void ask(boolean first) {
        if (first) {
            user.setQuestion(Constants.QUESTION);
        }
        System.out.println(user.getQuestion());
        System.out.println(user.getCode());
    }

    Optional<UserInput> getAnswer() {
        return Optional.ofNullable(user.getAnswer());
    }

    Optional<UserOutput> getUserOutput() {
        Type type = Type.valueOf(user.getAnswer());
        UserOutput output = UserOutput.builder().type(type).build();
        return Optional.ofNullable(output);
    }
}
