import javax.servlet.http.HttpSession;

import org.apache.commons.lang.StringEscapeUtils;

/**
 * 获取 URL 的内容。
 */
public class ClassXServlet extends HttpServlet {
    private static final long serialVersionUID = 1L;

    public void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        HttpSession session = request.getSession();
        String url = request.getParameter("url");
        String result = "";

        try {
            // 禁止访问本地回环地址
            if (url.contains("http://127.0.") || url.contains("http://localhost")) {
                result = "[url] contains [127.] or [localhost]: [url]";
            } else {
                BufferedReader br = new BufferedReader(new InputStreamReader(new URL(URLEncoder.encode(url, "UTF-8")).openStream()));
                String line;
                while ((line = br.readLine())!= null) {
                    result += line + "\n";
                }
            }
        } catch (Exception e) {
            result = e.getMessage();
        }

        session.setAttribute("result", StringEscapeUtils.escapeJava(result));
        request.getRequestDispatcher("/result.jsp").forward(request, response);
    }
}
