import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;

public class ClassX {
    /**
     * Mengambil konten dari URL.
     * 
     * Fungsi ini memblokir akses ke alamat loopback lokal untuk mencegah SSRF.
     */
    public static String getContent(String url) {
        StringBuilder response = new StringBuilder();
        try {
            URL website = new URL(url);
            BufferedReader reader = new BufferedReader(new InputStreamReader(website.openStream()));
            reader.lines().forEach(response::append);
            reader.close();
            return response.toString();
        } catch (Exception ex) {
            ex.printStackTrace();
            return null;
        }
    }
}
